#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <omp.h>  /* Added for OpenMP parallelism */

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"

/* Tunable blocking parameters for the GEMM kernel.
 * They can be overridden at compile time, e.g.:
 *   -DGEMM_BLOCK_I=64 -DGEMM_BLOCK_J=64 -DGEMM_BLOCK_K=32
 *
 * The defaults are chosen to give good cache locality on modern x86
 * (32x32 tiles fit comfortably in L1 data cache for doubles). */
#ifndef GEMM_BLOCK_I
# define GEMM_BLOCK_I 32
#endif

#ifndef GEMM_BLOCK_J
# define GEMM_BLOCK_J 32
#endif

#ifndef GEMM_BLOCK_K
# define GEMM_BLOCK_K 32
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      C[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) (i*(j+1) % nk) / nk;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+2) % nj) / nj;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  /* Use local restrict-qualified aliases to help the compiler
   * optimize memory accesses and enable better vectorization. */
  DATA_TYPE       (* restrict C_)[nj] = C;
  const DATA_TYPE (* restrict A_)[nk] = A;
  const DATA_TYPE (* restrict B_)[nj] = B;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

  int i, j, k;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop

  /* ------------------------------------------------------------------
   * Step 1: Scale C by beta (C = beta * C).
   *
   * This is pulled out of the main GEMM loop so that the GEMM itself
   * becomes a pure accumulation (C += alpha * A * B). This separation
   * has negligible cost compared to GEMM and simplifies blocking.
   *
   * The loop is parallelized over i and vectorized over j.
   * ------------------------------------------------------------------ */
#pragma omp parallel for schedule(static) private(j) if ((long)_PB_NI * _PB_NJ > 256L)
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE * restrict Ci = C_[i];
#pragma omp simd
    for (j = 0; j < _PB_NJ; j++) {
      Ci[j] *= beta_;
    }
  }

  /* ------------------------------------------------------------------
   * Step 2: Blocked matrix multiplication:
   *
   *   C += alpha * A * B
   *
   * Blocking (tiling) over i, j, and k improves data locality:
   *  - Each C sub-block is reused across the k-blocks.
   *  - Each B sub-block (rows over k, columns over j) is reused for
   *    all rows i in the i-block.
   *  - j is kept as the innermost loop to keep accesses to C and B
   *    contiguous in memory (row-major layout).
   *
   * The outer (ii, jj) tile loops are parallelized with OpenMP; each
   * thread owns a disjoint C tile and performs all k-accumulations
   * into that tile, eliminating write races.
   * ------------------------------------------------------------------ */
  const int block_i = GEMM_BLOCK_I;
  const int block_j = GEMM_BLOCK_J;
  const int block_k = GEMM_BLOCK_K;

#pragma omp parallel for collapse(2) schedule(static) private(i,j,k) if ((long)_PB_NI * _PB_NJ > 256L)
  for (int ii = 0; ii < _PB_NI; ii += block_i) {
    for (int jj = 0; jj < _PB_NJ; jj += block_j) {

      /* Actual bounds of this tile (handle edge tiles). */
      const int i_max = (ii + block_i < _PB_NI) ? (ii + block_i) : _PB_NI;
      const int j_max = (jj + block_j < _PB_NJ) ? (jj + block_j) : _PB_NJ;
      const int width = j_max - jj; /* Number of columns in this tile */

      for (int kk = 0; kk < _PB_NK; kk += block_k) {
        const int k_max = (kk + block_k < _PB_NK) ? (kk + block_k) : _PB_NK;

        /* Iterate over rows in the current i-tile. */
        for (i = ii; i < i_max; i++) {

          /* Pointer to the beginning of the current C row tile. */
          DATA_TYPE * restrict Ci = &C_[i][jj];

          /* Iterate over the current k-tile. */
          for (k = kk; k < k_max; k++) {
            const DATA_TYPE aik = alpha_ * A_[i][k];
            const DATA_TYPE * restrict Bk = &B_[k][jj];

            /* Innermost j-loop: contiguous over C and B, very
             * amenable to SIMD vectorization. */
#pragma omp simd
            for (j = 0; j < width; j++) {
              Ci[j] += aik * Bk[j];
            }
          }
        }
      }

    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
