/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

  /* Create local restrict-qualified views of the arrays.
   * This improves the compiler's alias analysis while remaining
   * semantically correct for this benchmark (A, B, C do not overlap). */
  DATA_TYPE (*restrict C_)[nj] = C;
  DATA_TYPE (*restrict A_)[nk] = A;
  DATA_TYPE (*restrict B_)[nj] = B;

  /* Cache local copies of loop bounds.  In PolyBench, _PB_*
   * may be macros with minor overhead; capturing them once
   * gives the compiler clearer, invariant bounds. */
  const int ni_lb = _PB_NI;
  const int nj_lb = _PB_NJ;
  const int nk_lb = _PB_NK;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop
  /* Parallelize across rows of C.  Each iteration of the i-loop works on
   * a distinct row of C and reads disjoint rows of A; B is read-only,
   * so there are no loop-carried dependencies across i. */
#pragma omp parallel for schedule(static) private(j,k)
  for (i = 0; i < ni_lb; i++) {
    /* Pointers to the current row of C and A to reduce address arithmetic. */
    DATA_TYPE *restrict Ci = C_[i];
    const DATA_TYPE *restrict Ai = A_[i];

    /* 1) Scale row i of C by beta.
     *    This loop is simple and contiguous in memory, enabling
     *    effective vectorization. */
    for (j = 0; j < nj_lb; j++)
      Ci[j] *= beta;

    /* 2) Compute alpha * A * B contribution for row i.
     *
     * We apply a 2D blocking of the k (reduction) and j (column) loops:
     *   - The k-blocking helps reuse elements of A[i][k] and B[k][*]
     *     in L1/L2 cache.
     *   - The j-blocking keeps the working set of C[i][*] and B[k][*]
     *     small, reducing cache misses on large matrices.
     *
     * The order of floating-point operations for each C[i][j] remains:
     *   scale by beta, then accumulation over k in increasing order,
     * as in the original implementation (only the loop nest structure
     * is changed). */
    for (int kk = 0; kk < nk_lb; kk += GEMM_BLOCK_K) {
      const int kend = (kk + GEMM_BLOCK_K < nk_lb) ? (kk + GEMM_BLOCK_K) : nk_lb;

      for (k = kk; k < kend; k++) {
        const DATA_TYPE a_ik = alpha * Ai[k];
        const DATA_TYPE *restrict Bk = B_[k];

        /* Tile columns (j) to improve locality on C and B. */
        for (int jj = 0; jj < nj_lb; jj += GEMM_BLOCK_J) {
          const int jend = (jj + GEMM_BLOCK_J < nj_lb) ? (jj + GEMM_BLOCK_J) : nj_lb;

          DATA_TYPE *restrict C_tile = Ci + jj;
          const DATA_TYPE *restrict B_tile = Bk + jj;

          /* Inner-most loop: simple, contiguous operations amenable
           * to auto-vectorization.  OpenMP 'simd' is a hint only;
           * if OpenMP is not enabled, this pragma is ignored. */
#pragma omp simd
          for (j = 0; j < jend - jj; j++) {
            C_tile[j] += a_ik * B_tile[j];
          }
        }
      }
    }
  }
#pragma endscop

}


