#endif
  for (int ii = 0; ii < NI; ii += GEMM_BLOCK_I) {
    const int i_end = (ii + GEMM_BLOCK_I < NI) ? (ii + GEMM_BLOCK_I) : NI;

    for (int kk = 0; kk < NK; kk += GEMM_BLOCK_K) {
      const int k_end = (kk + GEMM_BLOCK_K < NK) ? (kk + GEMM_BLOCK_K) : NK;

