        const int j_end = (jj + GEMM_BLOCK_J < NJ) ? (jj + GEMM_BLOCK_J) : NJ;

        for (i = ii; i < i_end; ++i) {
          const DATA_TYPE *restrict Ai = &A_[i][0];
          DATA_TYPE *restrict Ci = &C_[i][0];

